//! Manufacturer lookup for the first three bytes of a MAC address.
//!
//! A list of raw MAC addresses tells an operator nothing. "Hikvision" against
//! one of them tells them which box on the wall they are looking at, which is
//! the entire point of listing neighbours at all.
//!
//! This table is a deliberate subset, not the full registry: the ~52,000 public
//! assignments would dominate the binary, and almost all of them are for parts
//! nobody plugs into a camera network. It covers video-surveillance makers,
//! network equipment, and the common endpoint manufacturers. Anything else
//! reports as unknown, which is honest -- an unknown prefix means "not in this
//! list", never "not a real device".
//!
//! Generated from the IEEE public OUI registry (via the local nmap
//! `nmap-mac-prefixes` copy) rather than written from memory, so every entry
//! here was checked against the published assignment.

use serde::Serialize;

/// What a manufacturer suggests the device probably is. A guess, always.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum DeviceKind {
    /// Camera, recorder, or other video-surveillance equipment.
    Camera,
    /// Switch, router, access point, or firewall.
    Network,
    /// Computer, phone, or other endpoint.
    Endpoint,
}

