/// Look up the manufacturer for a MAC address.
///
/// Returns `None` for a prefix outside this subset, which is not the same as
/// the address being invalid.
pub fn lookup(mac: &str) -> Option<(&'static str, DeviceKind)> {
    let prefix: String = mac
        .chars()
        .filter(|c| c.is_ascii_hexdigit())
        .take(6)
        .collect::<String>()
        .to_ascii_uppercase();
    if prefix.len() < 6 {
        return None;
    }
    OUI_TABLE
        .binary_search_by(|(candidate, _, _)| candidate.cmp(&prefix.as_str()))
        .ok()
        .map(|index| (OUI_TABLE[index].1, OUI_TABLE[index].2))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_so_binary_search_is_valid() {
        // A single out-of-order entry would silently break lookups.
        for pair in OUI_TABLE.windows(2) {
            assert!(pair[0].0 < pair[1].0, "{} must sort before {}", pair[0].0, pair[1].0);
        }
    }

    #[test]
    fn every_prefix_is_six_hex_digits() {
        for (prefix, name, _) in OUI_TABLE {
            assert_eq!(prefix.len(), 6, "{prefix} for {name}");
            assert!(prefix.chars().all(|c| c.is_ascii_hexdigit() && !c.is_lowercase()));
        }
    }

    #[test]
    fn accepts_the_separators_macs_are_written_with() {
        // The same address in the three forms people paste.
        let colon = lookup("bc:45:29:ad:08:59");
        assert_eq!(colon, lookup("BC-45-29-AD-08-59"));
        assert_eq!(colon, lookup("bc4529ad0859"));
    }

    #[test]
    fn resolves_a_prefix_verified_against_the_registry() {
        // BC4529 is ZTE, confirmed against the published assignment; it is the
        // gateway on the network this was developed against.
        let (name, kind) = lookup("bc:45:29:ad:08:59").expect("known prefix");
        assert!(name.to_lowercase().contains("zte"), "got {name}");
        assert_eq!(kind, DeviceKind::Network);
    }

    #[test]
    fn an_unlisted_prefix_is_absent_not_wrong() {
        // Locally administered ranges are never assigned to anyone.
        assert_eq!(lookup("02:00:00:00:00:01"), None);
    }

    #[test]
    fn a_truncated_address_resolves_nothing() {
        assert_eq!(lookup("bc:45"), None);
        assert_eq!(lookup(""), None);
    }
}
